import { useEffect, useState } from 'react';
import { motion } from 'motion/react';

// ---- inlined from radixsort ----
/**
 * LSD radix sort trace over 24 distinct three-digit base-4 values. One frame per element
 * classified: the display order is the filled buckets so far followed by the untouched
 * remainder, so order visibly emerges from classification — no comparison ever happens.
 */

const RADIX_BASE = 4;
const RADIX_DIGITS = 3;
const RADIX_SIZE = 24;

const SEED = 20260318;

/** mulberry32: a fixed seed keeps every run identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Digit p of value (p=0 least significant), base 4. */
const digitOf = (value: number, p: number) => (value >> (2 * p)) & 3;

/** 24 distinct values in [0, 63]: shuffle 0..63, take the front. */
const random = seededRandom(SEED);
const deck = Array.from({ length: 64 }, (_, i) => i);
for (let i = deck.length - 1; i > 0; --i) {
  const j = Math.floor(random() * (i + 1));
  [deck[i], deck[j]] = [deck[j], deck[i]];
}
const radixValues = deck.slice(0, RADIX_SIZE);

interface RadixFrame {
  /** Values in display order for this frame. */
  order: number[];
  /** Which digit is being classified, or -1 before the sort and 3 once done. */
  pass: number;
  /** Elements already dropped into buckets this pass. */
  taken: number;
}

const frames: RadixFrame[] = [{ order: radixValues, pass: -1, taken: 0 }];

let current = radixValues;
for (let pass = 0; pass < RADIX_DIGITS; ++pass) {
  const buckets: number[][] = [[], [], [], []];
  current.forEach((value, j) => {
    buckets[digitOf(value, pass)].push(value);
    frames.push({ order: [...buckets.flat(), ...current.slice(j + 1)], pass, taken: j + 1 });
  });
  current = buckets.flat();
}
frames.push({ order: current, pass: RADIX_DIGITS, taken: 0 });

const radixFrames = frames;

const FRAME_MS = 110;
const HOLD_FRAMES = 26;
const TWEEN = { duration: FRAME_MS / 1000, ease: 'easeInOut' } as const;
const LAST = radixFrames.length - 1;
const DIGIT_NAMES = ['1s', '4s', '16s'];
const DIGIT_COLORS = ['#4269d0', '#efb118', '#ff725c', '#6cc5b0'];

/** Each element is a stack of three digit-color bands, most significant on top. */
export default function RadixSort({ width }: { width: number }) {
  const height = Math.round(width * 0.4);
  const pad = 8;
  const slot = Math.max(1, width - 2 * pad) / RADIX_SIZE;
  const bandWidth = slot * 0.68;
  const top = 12;
  const bandHeight = Math.max(1, height - top - 34) / RADIX_DIGITS;

  const [step, setStep] = useState(LAST);

  useEffect(() => {
    setStep(0);
    const id = window.setInterval(
      () => setStep((s) => (s + 1) % (radixFrames.length + HOLD_FRAMES)),
      FRAME_MS
    );
    return () => window.clearInterval(id);
  }, []);

  if (width === 0) return null;

  const frame = radixFrames[Math.min(step, LAST)];
  const sorting = frame.pass >= 0 && frame.pass < RADIX_DIGITS;
  const classified = sorting ? frame.taken : 0;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Least-significant-digit radix sort over 24 three-digit base-4 values, each drawn as a stack of digit-color bands. Every pass groups elements by one digit — the active band stays bright while the others dim — and sorted order emerges from three rounds of classification without a single comparison"
    >
      {frame.order.map((value, i) => (
        <motion.g
          key={value}
          initial={false}
          animate={{ x: pad + i * slot + (slot - bandWidth) / 2 }}
          transition={TWEEN}
        >
          {[2, 1, 0].map((digit) => (
            <rect
              key={digit}
              y={top + (RADIX_DIGITS - 1 - digit) * bandHeight}
              width={bandWidth}
              height={bandHeight - 1}
              fill={DIGIT_COLORS[digitOf(value, digit)]}
              opacity={sorting && digit !== frame.pass ? 0.28 : 0.95}
              rx={1}
            />
          ))}
        </motion.g>
      ))}
      {sorting && classified > 0 && (
        <line
          x1={pad}
          x2={pad + classified * slot - (slot - bandWidth) / 2}
          y1={height - 26}
          y2={height - 26}
          stroke="var(--accent)"
          strokeWidth={2}
        />
      )}
      <text x={pad} y={height - 8} fill="var(--muted)" fontSize={11}>
        {frame.pass < 0
          ? `${RADIX_SIZE} three-digit base-4 values, unsorted`
          : sorting
            ? `pass ${frame.pass + 1} of 3 · grouping by the ${DIGIT_NAMES[frame.pass]} digit`
            : 'sorted, and no two values were ever compared'}
      </text>
      <text x={width - pad} y={height - 8} textAnchor="end" fill="var(--muted)" fontSize={11}>
        comparisons: 0
      </text>
    </svg>
  );
}
